static int cs35l45_set_prot_regs(struct cs35l45_private *cs35l45, bool vendor)
{
	int ret;

	/*
	 * prot_regs_set means "restore needed": a requested vendor setup is
	 * always written in full, even after a failed setup and rollback.
	 */
	if (!vendor && !cs35l45->prot_regs_set)
		return 0;

	if (vendor) {
		/* From the first write on, a stop has to restore the defaults. */
		cs35l45->prot_regs_set = true;
		ret = regmap_multi_reg_write(cs35l45->regmap, cs35l45_vendor_prot_regs,
					     ARRAY_SIZE(cs35l45_vendor_prot_regs));
		if (!ret)
			ret = regmap_set_bits(cs35l45->regmap, CS35L45_BLOCK_ENABLES2,
					      CS35L45_BBPE_EN_MASK);
	} else {
		ret = regmap_clear_bits(cs35l45->regmap, CS35L45_BLOCK_ENABLES2,
					CS35L45_BBPE_EN_MASK);
		if (!ret)
			ret = regmap_multi_reg_write(cs35l45->regmap, cs35l45_default_prot_regs,
						     ARRAY_SIZE(cs35l45_default_prot_regs));
		if (!ret)
			cs35l45->prot_regs_set = false;
	}

	if (ret)
		dev_err(cs35l45->dev, "Failed to set %s protection registers: %d\n",
			vendor ? "vendor" : "default", ret);
	else
		dev_dbg(cs35l45->dev, "%s protection registers\n", vendor ? "vendor" : "default");

	return ret;
}

static void cs35l45_prot_restore_failed(struct cs35l45_private *cs35l45)
{
	int ret;

	dev_err(cs35l45->dev,
		"protection registers not restored, switching the amplifier off\n");
	ret = regmap_write(cs35l45->regmap, CS35L45_GLOBAL_ENABLES, 0);
	if (ret && cs35l45->reset_gpio) {
		/* Out of reach over I2C: hold it in reset until it is rebound */
		dev_err(cs35l45->dev,
			"cannot switch the amplifier off (%d), holding it in reset\n", ret);
		gpiod_set_value_cansleep(cs35l45->reset_gpio, 0);
	}
}

static int cs35l45_global_en_ev(struct snd_soc_dapm_widget *w,
				struct snd_kcontrol *kcontrol, int event)
{
	struct snd_soc_component *component = snd_soc_dapm_to_component(w->dapm);
	struct cs35l45_private *cs35l45 = snd_soc_component_get_drvdata(component);
	int ret;

	dev_dbg(cs35l45->dev, "%s event : %x\n", __func__, event);

	switch (event) {
	case SND_SOC_DAPM_POST_PMU:
		/*
		 * The protection operating point is still set although its
		 * firmware does not run: an earlier rollback failed. Restore
		 * the defaults first, and leave the amplifier off (a DAPM
		 * event error is only logged) while that fails.
		 */
		if (cs35l45->prot_regs_set && !cs35l45->dsp.cs_dsp.running) {
			ret = cs35l45_set_prot_regs(cs35l45, false);
			if (ret) {
				dev_err(cs35l45->dev,
					"protection registers not restored, amplifier stays off\n");
				return ret;
			}
		}

		regmap_write(cs35l45->regmap, CS35L45_GLOBAL_ENABLES,
			     CS35L45_GLOBAL_EN_MASK);

		usleep_range(CS35L45_POST_GLOBAL_EN_US, CS35L45_POST_GLOBAL_EN_US + 100);
		break;
	case SND_SOC_DAPM_PRE_PMD:
		usleep_range(CS35L45_PRE_GLOBAL_DIS_US, CS35L45_PRE_GLOBAL_DIS_US + 100);

		regmap_write(cs35l45->regmap, CS35L45_GLOBAL_ENABLES, 0);
		break;
	default:
		break;
	}

	return 0;
}

static const struct reg_sequence cs35l45_vendor_prot_regs[] = {
	{ CS35L45_BOOST_LPMODE_CFG,	0x00000003 },
	{ CS35L45_BST_BPE_IL_LIM_THLD,	0x0000002C },
	{ CS35L45_LDPM_CONFIG,		0x00019EDE },
	{ CS35L45_MIXER_PILOT0_INPUT,	CS35L45_PCM_SRC_DSP_TX2 },
};

static const struct reg_sequence cs35l45_default_prot_regs[] = {
	{ CS35L45_BOOST_LPMODE_CFG,	0x00000002 },
	{ CS35L45_BST_BPE_IL_LIM_THLD,	0x0006022C },
	{ CS35L45_LDPM_CONFIG,		0x0001B636 },
	{ CS35L45_MIXER_PILOT0_INPUT,	CS35L45_PCM_SRC_ZERO },
};

static void msm_kms_fb_unpin_work(struct kthread_work *work)
{
	struct msm_fb_unpin_work *unpin =
		container_of(to_drm_vblank_work(work), struct msm_fb_unpin_work,
			     base);
	struct msm_kms_fb_unpin *pending = unpin->pending;
	u64 count, target = 0;

	spin_lock(&pending->lock);
	if (list_empty(&unpin->node)) {
		spin_unlock(&pending->lock);
		return;
	}

	/*
	 * An async commit (msm_atomic_commit_tail()) cleans its planes up
	 * before its deferred flush has run: the old framebuffer is fetched
	 * until a vblank after that flush. Look again at the next vblank
	 * while the flush is outstanding.
	 */
	if (unpin->await_flush) {
		count = drm_crtc_vblank_count(unpin->crtc);
		if (pending->flush_seq == unpin->flush_seq)
			target = count + 1;
		else if (count <= pending->flush_vbl)
			target = pending->flush_vbl + 1;
	}
	/* A crtc in modeset refuses: it does not scan out any more. */
	if (target && drm_vblank_work_schedule(&unpin->base, target, true) == 1) {
		spin_unlock(&pending->lock);
		return;
	}

	list_del_init(&unpin->node);
	spin_unlock(&pending->lock);

	msm_kms_fb_unpin_release(unpin);
}

void msm_kms_fb_unpin_flushed(struct msm_kms *kms, unsigned int crtc_mask)
{
	struct drm_crtc *crtc;

	for_each_crtc_mask(kms->dev, crtc, crtc_mask) {
		unsigned int idx = drm_crtc_index(crtc);
		struct msm_kms_fb_unpin *pending;

		if (idx >= ARRAY_SIZE(kms->fb_unpin))
			continue;

		pending = &kms->fb_unpin[idx];
		spin_lock(&pending->lock);
		pending->flush_seq++;
		pending->flush_vbl = drm_crtc_vblank_count(crtc);
		spin_unlock(&pending->lock);
	}
}

static bool msm_crtc_fb_unpin_fallback(struct drm_crtc *crtc,
				       struct drm_framebuffer *fb)
{
	if (msm_crtc_wait_one_vblank(crtc))
		return false;

	drm_err_ratelimited(crtc->dev,
			    "crtc %u: end of scanout of FB %u unknown, keeping it pinned\n",
			    crtc->base.id, fb->base.id);
	drm_framebuffer_get(fb);

	return true;
}

bool msm_crtc_queue_fb_unpin(struct drm_crtc *crtc, struct drm_framebuffer *fb)
{
	struct msm_drm_private *priv = crtc->dev->dev_private;
	struct msm_kms *kms = priv->kms;
	unsigned int idx = drm_crtc_index(crtc);
	struct msm_kms_fb_unpin *pending;
	struct msm_fb_unpin_work *unpin;
	int ret = 0;

	if (!kms || idx >= ARRAY_SIZE(kms->fb_unpin))
		return false;

	pending = &kms->fb_unpin[idx];

	unpin = kzalloc_obj(*unpin);
	if (!unpin)
		return msm_crtc_fb_unpin_fallback(crtc, fb);

	unpin->fb = fb;
	unpin->crtc = crtc;
	unpin->pending = pending;
	drm_framebuffer_get(fb);

	drm_vblank_work_init(&unpin->base, crtc, msm_kms_fb_unpin_work);

	/*
	 * Publish and schedule under the lock: msm_crtc_vblank_off() must
	 * not take the work off the list and free it in between.
	 *
	 * Whether the crtc still scans out is not read from crtc->state: a
	 * later commit may already have swapped in a state that switches it
	 * off while the hardware still fetches. Ask the vblank machinery,
	 * which follows the hardware: drm_vblank_work_schedule() returns 0
	 * for a crtc in modeset (never enabled since reset, or past
	 * drm_crtc_vblank_off(), which runs after the interface is disabled),
	 * and ->off covers msm_crtc_vblank_off() up to that point.
	 */
	spin_lock(&pending->lock);
	unpin->await_flush = READ_ONCE(kms->pending_crtc_mask) &
			     drm_crtc_mask(crtc);
	unpin->flush_seq = pending->flush_seq;
	if (!pending->off) {
		list_add_tail(&unpin->node, &pending->fbs);
		ret = drm_vblank_work_schedule(&unpin->base,
					       drm_crtc_vblank_count(crtc) + 1,
					       true);
		if (ret == 1) {
			spin_unlock(&pending->lock);
			return true;
		}
		list_del_init(&unpin->node);
	}
	spin_unlock(&pending->lock);

	drm_framebuffer_put(fb);
	kfree(unpin);

	/* No vblank reference (vblank enable failed) while maybe scanning out */
	if (ret < 0)
		return msm_crtc_fb_unpin_fallback(crtc, fb);

	return false;
}

static bool msm_crtc_wait_one_vblank(struct drm_crtc *crtc)
{
	wait_queue_head_t *queue = drm_crtc_vblank_waitqueue(crtc);
	long left;
	u64 count;
	int ret;

	ret = drm_crtc_vblank_get(crtc);
	if (ret)
		return ret == -EINVAL;

	count = drm_crtc_vblank_count(crtc);
	left = wait_event_timeout(*queue, drm_crtc_vblank_count(crtc) != count,
				  msecs_to_jiffies(100));

	drm_crtc_vblank_put(crtc);

	return left > 0;
}

int q6afe_unvote_lpass_core_hw(struct device *dev, uint32_t hw_block_id,
			       uint32_t client_handle)
{
	struct q6afe *afe = dev_get_drvdata(dev->parent);
	struct afe_cmd_remote_lpass_core_hw_devote_request *vote_cfg;
	struct apr_pkt *pkt;
	int ret = 0;
	int pkt_size = APR_HDR_SIZE + sizeof(*vote_cfg);

	/* The DSP never hands out handle 0; a devote quoting it fails. */
	if (!client_handle) {
		dev_err(afe->dev, "no handle to unvote hw block %u\n",
			hw_block_id);
		return -EINVAL;
	}

	void *p __free(kfree) = kzalloc(pkt_size, GFP_KERNEL);
	if (!p)
		return -ENOMEM;

	pkt = p;
	vote_cfg = p + APR_HDR_SIZE;

	pkt->hdr.hdr_field = APR_HDR_FIELD(APR_MSG_TYPE_SEQ_CMD,
					   APR_HDR_LEN(APR_HDR_SIZE),
					   APR_PKT_VER);
	pkt->hdr.pkt_size = pkt_size;
	pkt->hdr.src_port = 0;
	pkt->hdr.dest_port = 0;
	pkt->hdr.token = hw_block_id;
	pkt->hdr.opcode = AFE_CMD_REMOTE_LPASS_CORE_HW_DEVOTE_REQUEST;
	vote_cfg->hw_block_id = hw_block_id;
	vote_cfg->client_handle = client_handle;

	ret = apr_send_pkt(afe->apr, pkt);
	if (ret < 0)
		dev_err(afe->dev, "AFE failed to unvote (%d)\n", hw_block_id);

	return ret;
}

int q6afe_vote_lpass_core_hw(struct device *dev, uint32_t hw_block_id,
			     const char *client_name, uint32_t *client_handle)
{
	struct q6afe *afe = dev_get_drvdata(dev->parent);
	struct afe_cmd_remote_lpass_core_hw_vote_request *vote_cfg;
	struct apr_pkt *pkt;
	int ret = 0;
	int pkt_size = APR_HDR_SIZE + sizeof(*vote_cfg);

	void *p __free(kfree) = kzalloc(pkt_size, GFP_KERNEL);
	if (!p)
		return -ENOMEM;

	pkt = p;
	vote_cfg = p + APR_HDR_SIZE;

	pkt->hdr.hdr_field = APR_HDR_FIELD(APR_MSG_TYPE_SEQ_CMD,
					   APR_HDR_LEN(APR_HDR_SIZE),
					   APR_PKT_VER);
	pkt->hdr.pkt_size = pkt_size;
	pkt->hdr.src_port = 0;
	pkt->hdr.dest_port = 0;
	pkt->hdr.token = hw_block_id;
	pkt->hdr.opcode = AFE_CMD_REMOTE_LPASS_CORE_HW_VOTE_REQUEST;
	vote_cfg->hw_block_id = hw_block_id;
	strscpy(vote_cfg->client_name, client_name,
			sizeof(vote_cfg->client_name));

	if (hw_block_id >= AFE_LPASS_CORE_HW_BLOCK_MAX)
		return -EINVAL;

	/* CCF prepare_lock serialises votes, so the slot is ours until read. */
	afe->lpass_hw_handle[hw_block_id] = 0;
	ret = afe_apr_send_pkt(afe, pkt, NULL,
			       AFE_CMD_RSP_REMOTE_LPASS_CORE_HW_VOTE_REQUEST);
	if (ret)
		dev_err(afe->dev, "AFE failed to vote (%d)\n", hw_block_id);
	else
		*client_handle = afe->lpass_hw_handle[hw_block_id];

	return ret;
}

static int q6asm_dai_close(struct snd_soc_component *component,
			   struct snd_pcm_substream *substream)
{
	struct snd_pcm_runtime *runtime = substream->runtime;
	struct snd_soc_pcm_runtime *soc_prtd = snd_soc_substream_to_rtd(substream);
	struct q6asm_dai_rtd *prtd = runtime->private_data;

	if (prtd->audio_client) {
		if (prtd->state == Q6ASM_STREAM_RUNNING) {
			q6asm_cmd(prtd->audio_client, prtd->stream_id,
				  CMD_CLOSE);
			q6asm_unmap_memory_regions(substream->stream,
					   prtd->audio_client);
		}
		q6asm_audio_client_free(prtd->audio_client);
		prtd->audio_client = NULL;
	}
	q6routing_stream_close(soc_prtd->dai_link->id,
						substream->stream);
	kfree(prtd);
	return 0;
}

static int dwc3_gadget_soft_connect(struct dwc3 *dwc)
{
	int ret;

	/*
	 * In the Synopsys DWC_usb31 1.90a programming guide section
	 * 4.1.9, it specifies that for a reconnect after a
	 * device-initiated disconnect requires a core soft reset
	 * (DCTL.CSftRst) before enabling the run/stop bit.
	 */
	ret = dwc3_core_soft_reset(dwc);
	if (ret)
		return ret;

	dwc3_event_buffers_setup(dwc);
	__dwc3_gadget_start(dwc);
	return dwc3_gadget_run_stop(dwc, true);
}

static void dwc3_qcom_bw_work(struct work_struct *work)
{
	struct dwc3_qcom *qcom = container_of(to_delayed_work(work),
					      struct dwc3_qcom, bw_work);

	mutex_lock(&qcom->bw_lock);
	qcom->bw_role_hold = false;
	dwc3_qcom_bw_prune(qcom);
	dwc3_qcom_bw_apply(qcom);
	mutex_unlock(&qcom->bw_lock);
}

static void qcom_battmgr_callback(const void *data, size_t len, void *priv)
{
	const struct pmic_glink_hdr *hdr = data;
	struct qcom_battmgr *battmgr = priv;
	unsigned int opcode = le32_to_cpu(hdr->opcode);

	if (opcode == BATTMGR_NOTIFICATION)
		qcom_battmgr_notification(battmgr, data, len);
	else if (battmgr->variant == QCOM_BATTMGR_SC8280XP ||
		 battmgr->variant == QCOM_BATTMGR_X1E80100)
		qcom_battmgr_sc8280xp_callback(battmgr, data, len);
	else
		qcom_battmgr_sm8350_callback(battmgr, data, len);
}

static int qcom_battmgr_btm_otg_send_locked(struct qcom_battmgr *battmgr,
					    bool on)
{
	struct qcom_battmgr_asus_btm_otg_msg request = {
		.hdr.owner = cpu_to_le32(PMIC_GLINK_OWNER_ASUS_ROG5),
		.hdr.type = cpu_to_le32(PMIC_GLINK_REQ_RESP),
		.hdr.opcode = cpu_to_le32(ASUS_ROG5_SET_BTM_OTG),
		.on = cpu_to_le32(on),
	};

	return qcom_battmgr_asus_request_locked(battmgr, &request,
						sizeof(request));
}

static int qcom_battmgr_btm_otg_is_enabled(struct regulator_dev *rdev)
{
	struct qcom_battmgr *battmgr = rdev_get_drvdata(rdev);

	return READ_ONCE(battmgr->btm_otg_on);
}

static int __fastrpc_buf_alloc(struct fastrpc_user *fl, struct device *dev,
			     u64 size, struct fastrpc_buf **obuf)
{
	struct fastrpc_buf *buf;

	buf = kzalloc_obj(*buf);
	if (!buf)
		return -ENOMEM;

	INIT_LIST_HEAD(&buf->attachments);
	INIT_LIST_HEAD(&buf->node);
	mutex_init(&buf->lock);

	buf->cctx = fl->cctx;
	buf->virt = NULL;
	buf->dma_addr = 0;
	buf->size = size;
	buf->dev = dev;
	buf->raddr = 0;

	buf->virt = dma_alloc_coherent(dev, buf->size, &buf->dma_addr,
				       GFP_KERNEL);
	if (!buf->virt) {
		mutex_destroy(&buf->lock);
		kfree(buf);
		return -ENOMEM;
	}

	*obuf = buf;

	return 0;
}

static void fastrpc_buf_free(struct fastrpc_buf *buf)
{
	dma_free_coherent(buf->dev, buf->size, buf->virt,
			  fastrpc_ipa_to_dma_addr(buf->cctx, buf->dma_addr));
	kfree(buf);
}

static void fastrpc_release(struct dma_buf *dmabuf)
{
	struct fastrpc_buf *buffer = dmabuf->priv;
	struct fastrpc_channel_ctx *cctx = buffer->cctx;

	fastrpc_buf_free(buffer);
	/* Taken in fastrpc_dmabuf_alloc() */
	fastrpc_channel_ctx_put(cctx);
}

static int msm_dp_ctrl_train_link_downshift(struct msm_dp_ctrl_private *ctrl,
					    bool strict)
{
	int rc = 0;
	int link_train_max_retries = 5;
	u8 link_status[DP_LINK_STATUS_SIZE];
	unsigned int training_step;

	while (--link_train_max_retries) {
		training_step = DP_TRAINING_NONE;
		rc = msm_dp_ctrl_setup_main_link(ctrl, &training_step);
		if (rc == 0) {
			/* training completed successfully */
			return 0;
		} else if (training_step == DP_TRAINING_1) {
			/* link train_1 failed */
			if (!msm_dp_aux_is_link_connected(ctrl->aux))
				break;

			drm_dp_dpcd_read_link_status(ctrl->aux, link_status);

			rc = msm_dp_ctrl_link_rate_down_shift(ctrl);
			if (rc < 0) { /* already in RBR = 1.6G */
				if (msm_dp_ctrl_clock_recovery_any_ok(link_status,
					ctrl->link->link_params.num_lanes)) {
					/*
					 * some lanes are ready,
					 * reduce lane number
					 */
					rc = msm_dp_ctrl_link_lane_down_shift(ctrl);
					if (rc < 0) { /* lane == 1 already */
						/* end with failure */
						break;
					}
				} else {
					/* end with failure */
					break; /* lane == 1 already */
				}
			}
		} else if (training_step == DP_TRAINING_2) {
			/* link train_2 failed */
			if (!msm_dp_aux_is_link_connected(ctrl->aux))
				break;

			drm_dp_dpcd_read_link_status(ctrl->aux, link_status);

			if (!drm_dp_clock_recovery_ok(link_status,
					ctrl->link->link_params.num_lanes))
				rc = msm_dp_ctrl_link_rate_down_shift(ctrl);
			else
				rc = msm_dp_ctrl_link_lane_down_shift(ctrl);

			if (rc < 0) {
				/* end with failure */
				break; /* lane == 1 already */
			}

			/* stop link training before start re training  */
			msm_dp_ctrl_clear_training_pattern(ctrl, DP_PHY_DPRX);
		}

		rc = msm_dp_ctrl_reinitialize_mainlink(ctrl);
		if (rc) {
			DRM_ERROR("Failed to reinitialize mainlink. rc=%d\n", rc);
			break;
		}
	}

	if (strict && !rc)
		rc = -ETIMEDOUT;

	return rc;
}

void msm_dp_ctrl_phy_init(struct msm_dp_ctrl *msm_dp_ctrl)
{
	struct msm_dp_ctrl_private *ctrl;
	struct phy *phy;

	ctrl = container_of(msm_dp_ctrl, struct msm_dp_ctrl_private, msm_dp_ctrl);
	phy = ctrl->phy;

	msm_dp_ctrl_phy_reset(ctrl);
	phy_init(phy);
}

void msm_dp_ctrl_phy_exit(struct msm_dp_ctrl *msm_dp_ctrl)
{
	struct msm_dp_ctrl_private *ctrl;
	struct phy *phy;

	ctrl = container_of(msm_dp_ctrl, struct msm_dp_ctrl_private, msm_dp_ctrl);
	phy = ctrl->phy;

	msm_dp_ctrl_phy_reset(ctrl);
	phy_exit(phy);
}
